    {"id": "saetze", "label": "Ganze Sätze", "sektion": "saetze", "baut_auf": ["satzbau", "faelle1", "faelle3", "vergangenheit", "zukunft", "routine", "reisen"], "tipp": "Nur ganze Sätze aus den Wörtern der vorherigen Levels.",
     "words": [
        # Dieses Level hat keine neuen Wörter. Jeder Satz besteht aus Wörtern
        # der vorherigen Levels – Wiederholung im Zusammenhang.
        {"de": "Ich habe zwei Brüder",              "bs": "Imam dva brata"},
        {"de": "Meine Schwester ist fünf Jahre alt",    "bs": "Moja sestra ima pet godina"},
        {"de": "Wir essen um sieben Uhr",           "bs": "Jedemo u sedam sati"},
        {"de": "Am Montag gehe ich zur Arbeit",     "bs": "U ponedjeljak idem na posao"},
        {"de": "Der Kaffee ist heiß",               "bs": "Kahva je vruća"},
        {"de": "Ich trinke Wasser, danke",          "bs": "Pijem vodu, hvala"},
        {"de": "Mein Papa arbeitet im Juli nicht",  "bs": "Moj babo ne radi u julu"},
        {"de": "Wo ist die rote Tasche?",           "bs": "Gdje je crvena torba?"},
        {"de": "Wie viel kostet das Brot?",         "bs": "Koliko košta hljeb?"},
        {"de": "Heute ist es kalt und es regnet",   "bs": "Danas je hladno i pada kiša"},
        {"de": "Ich verstehe ein bisschen Bosnisch", "bs": "Razumijem malo bosanski"},
        {"de": "Wir sehen uns am Samstag",          "bs": "Vidimo se u subotu"},
        {"de": "Ich möchte drei Äpfel, bitte",      "bs": "Htjela bih tri jabuke, molim"},
        {"de": "Meine Oma wohnt im Dorf",           "bs": "Moja nana stanuje u selu"},
        {"de": "Ich lerne jeden Tag Bosnisch",      "bs": "Učim bosanski svaki dan"},
        {"de": "Der Bus kommt um zehn",             "bs": "Autobus dolazi u deset"},
        {"de": "Ich habe Kopfschmerzen und Fieber", "bs": "Imam glavobolju i temperaturu"},
        {"de": "Das Wasser im See ist blau",        "bs": "Voda u jezeru je plava"},
        {"de": "Ich denke, dass meine Schwester zu Hause ist", "bs": "Mislim da je moja sestra kod kuće"},
        {"de": "Ich weiß nicht, wann der Bus kommt",   "bs": "Ne znam kada dolazi autobus"},
        {"de": "Wenn es regnet, bleibe ich zu Hause",  "bs": "Ako pada kiša, ostajem kod kuće"},
        {"de": "Gestern habe ich Brot und Milch gekauft (Frau)", "bs": "Jučer sam kupila hljeb i mlijeko"},
        {"de": "Nächstes Jahr werden wir ein Haus kaufen", "bs": "Sljedeće godine ćemo kupiti kuću"},
        {"de": "Mein Bruder ist älter als ich, aber kleiner", "bs": "Moj brat je stariji od mene, ali manji"},
    ]},
