        {"de": "Gehen wir heute Abend aus?", "bs": "Hoćemo li večeras izaći?"},
        {"de": "hinausgehen / ausgehen",     "bs": "izlaziti", "partner": "izaći"},
        {"de": "Am Wochenende gehe ich gern mit Freunden aus.", "bs": "Vikendom rado izlazim s prijateljima."},
        {"de": "fahren (ein Fahrzeug)",      "bs": "voziti"},
        {"de": "Fahr nicht so schnell!",     "bs": "Ne vozi tako brzo!"},
        {"de": "reisen",                     "bs": "putovati"},
        {"de": "Ich reise gern mit dem Zug.", "bs": "Volim putovati vozom."},
