    # ---- Sektion 12 · Körper und Gesundheit: Wortschatz-Paket 3 (01.11.2026) ----
    # Nr. 1-103 aus Release\Wortschatz\paket_03.json (Der Koerper,
    # Beschwerden, Beim Arzt, Apotheke und gesund leben), von Ajdin am
    # 31.10./01.11.2026 durchgesehen. Jedes Wort direkt vor seinem Beispielsatz.
    # - Ajdins Entscheidungen: prsa statt grudi (grudi zaehlt nicht),
    #   Doppelformen srčani udar / infarkt, svrbjeti / svrbiti, apotekar /
    #   farmaceut, toplomjer / termometar. Zaehlen NICHT: prepisati (heisst
    #   abschreiben), rentgen. Weitere Formen in "auch" nur, wo das Paket sie
    #   nennt (proliv, dijareja, nateći, naočare, smršaviti, ugojiti se, na
    #   prazan želudac, natašte).
    # - Gleiche Schreibung: jezik (Zunge) neben jezik (Sprache, Level
    #   nationalitaeten) - dasselbe bs schliesst distractors() in
    #   web/index.html ohnehin aus. Im Satz zu zavoj ist sestra die
    #   Krankenschwester (medicinska sestra).
    # - trudna gibt es nur weiblich, deshalb ohne weitere Formen.
