    # Level 53 · Im Restaurant: essen & zahlen
    {"kat": "resto2", "bs": "Ovo meso je ljuto.", "auch": ["Ljuto je ovo meso."], "de": "Dieses Fleisch ist scharf.", "quelle": "saetze"},
