    {"kat": "laender", "bs": "Moja porodica je iz Bosne", "auch": ["Iz Bosne je moja porodica", "Moja je porodica iz Bosne"], "de": "Meine Familie ist aus Bosnien", "quelle": "vokabel"},
    # Level 57 · Nationalitäten & Sprachen
